// THE REFUSAL HAPPENS HERE, BEFORE ANY WORK.
// lead.js sends the guard as a header, not in the body, and the whole point of
// that choice is that this workflow can decide to stop before it reads, parses
// or logs one field of a stranger's payload. So this node touches
// $json.headers only on the unauthorized path.
//
// The expected value is read from $env.NEXUS_NOTIFY_WEBHOOK_SECRET. It is NOT
// written down in this file and must never be: a workflow JSON lives in git and
// is exported, copied and pasted by people, and a secret pasted into one is a
// secret that has left the building.
//
// n8n only exposes $env inside a Code node when N8N_BLOCK_ENV_ACCESS_IN_NODE is
// false (the default). If that is turned on, this returns unconfigured and the
// workflow refuses everything rather than silently accepting everything --
// which is the direction a guard must fail in.

const h = $input.first().json.headers || {};
const PRESENTED = String(h['x-nexus-notify-secret'] || '');
const EXPECTED = String($env.NEXUS_NOTIFY_WEBHOOK_SECRET || '');

const ip = String(h['x-forwarded-for'] || '').split(',')[0].trim() || 'unknown';

if (!EXPECTED) {
  return [{ json: { authorized: false, reason: 'guard_not_configured', ip } }];
}

// Length-independent compare. Not constant time in the cryptographic sense --
// JS string indexing is not -- but it does not early-exit on the first wrong
// character, which is the leak that matters over a network.
function equal(a, b) {
  let diff = a.length ^ b.length;
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}

if (!equal(PRESENTED, EXPECTED)) {
  return [{ json: { authorized: false, reason: PRESENTED ? 'secret_mismatch' : 'secret_absent', ip } }];
}

// Authorized. Only now do we look at the body, and only at the seven fields
// lead.js says it sends. The mail body is composed HERE from these fields and
// never taken from the caller -- a caller holding the header still cannot make
// the message arbitrary text. That is deliberate and must stay: see the comment
// in apps/marketing-site/api/lead.js above the fetch().
const b = $input.first().json.body || {};
const take = (v, max) => String(v == null ? '' : v).replace(/[\x00-\x1F\x7F]/g, '').trim().slice(0, max);

const enquiry = {
  full_name:     take(b.full_name, 120),
  phone:         take(b.phone, 32),
  email:         take(b.email, 160),
  dealership:    take(b.dealership, 160),
  stock_size:    take(b.stock_size, 40),
  message:       take(b.message, 1500),
  submission_id: take(b.submission_id, 80),
};

// The site already refuses a nameless enquiry with 400. If one arrives anyway
// the endpoint moved or the check regressed; say so rather than mailing a blank.
if (!enquiry.full_name) {
  return [{ json: { authorized: false, reason: 'authorized_but_empty_name', ip } }];
}

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const row = (label, value) => value ? '<tr><td style="padding:4px 12px 4px 0;color:#666">' + label + '</td><td style="padding:4px 0"><strong>' + esc(value) + '</strong></td></tr>' : '';

const html =
  '<p>A new enquiry arrived from the NEXUS marketing site.</p>' +
  '<table style="border-collapse:collapse;font:14px/1.5 -apple-system,Segoe UI,sans-serif">' +
  row('Name', enquiry.full_name) +
  row('Phone', enquiry.phone) +
  row('Email', enquiry.email) +
  row('Dealership', enquiry.dealership) +
  row('Stock size', enquiry.stock_size) +
  '</table>' +
  (enquiry.message ? '<p style="margin-top:16px;color:#666">Message</p><blockquote style="margin:0;padding:8px 12px;border-left:3px solid #ddd;white-space:pre-wrap">' + esc(enquiry.message) + '</blockquote>' : '') +
  '<hr><p style="font:12px -apple-system,sans-serif;color:#999">submission_id: ' + esc(enquiry.submission_id || '(none sent)') +
  '<br>This person is a prospect for NEXUS. They are NOT a car buyer and do not belong in any dealership pipeline.</p>';

const subject = 'NEXUS enquiry: ' + enquiry.full_name + (enquiry.dealership ? ' (' + enquiry.dealership + ')' : '');

return [{ json: { authorized: true, ip, enquiry, subject, html } }];

// DELIVERY REPORT -- verify the claim before anything writes it down.
//
// The Gmail node runs with onError:'continueRegularOutput' so that a failed
// send reaches an audit row instead of vanishing into a red execution with no
// record. That swallow is ONLY safe because this node looks at what came out.
//
// Measured 2026-09: 5 of the 6 WhatsApp send nodes in this repo use the same
// onError and then write "we said this" unconditionally, so the audit trail
// asserts sends that never landed. This node is the difference. Do not delete
// it and leave the onError in place -- that combination is the defect.

const item = $input.first().json || {};
const err = item.error;

let sent = true, why = null;
if (err !== undefined) {
  sent = false;
  why = String((err && (err.message || err.description)) || err).slice(0, 300);
} else if (!item.id && !item.threadId && !item.messageId) {
  // Gmail returns the created message. No id means we have no evidence a
  // message exists, and "no evidence" is not "sent".
  sent = false;
  why = 'gmail node returned no message id';
}

const g = $('Guard: Secret and Allowlist').first().json;

return [{ json: {
  sent,
  why,
  status: sent ? 'SUCCESS' : 'FAILED',
  enquiry: g.enquiry,
  ip: g.ip,
} }];
